-- Classificação das ponteiras dos engates removíveis (fonte: Planilha sem título / Plano de Prod.).
-- P = PEQUENA (chapa 12 mm), M = MEDIA (chapa 12 mm), G = GRANDE (chapa 16 mm).
-- Casos HP, Não/Aplic., Nova/Rem e vazio foram preservados para revisão manual.

UPDATE "Modelo" SET "tamanhoPonteira" = 'PEQUENA', "updatedAt" = CURRENT_TIMESTAMP WHERE "codigo" IN ('AD1013', 'BM1000', 'BM1004', 'CH1005', 'DG1001', 'DG1005', 'FN1000', 'FO2000', 'FO2014', 'FO2017', 'FO2026', 'FO2046A', 'FO2048', 'FO2051', 'FO2052', 'FO2054', 'FO2055', 'FO2056', 'FO2057', 'FT4040', 'FT4040X', 'FT4054', 'FT4064', 'FT4065', 'FT4066', 'FT4066P', 'FT4068', 'GM3005', 'GM3005X', 'GM3021', 'GM3027', 'GM3066', 'GM3067', 'GW1002', 'HO1025', 'HY1017', 'HY1021', 'JP1006', 'JP1008', 'JP1010', 'JP1012', 'LI1000', 'LM1000', 'LR1001', 'LR1002', 'LR1006', 'LR1008', 'LR1010', 'LX1001', 'ME1000', 'ME1003', 'ME1005', 'MG1000', 'MI1002', 'MI1004A', 'MI1007', 'MI1008', 'MI1011', 'MI1012', 'MI1014', 'MI1019', 'MI1020', 'MI1021', 'MI1023', 'MI1023P', 'NI1002', 'NI1012', 'NI1018', 'NI1019', 'PE1028', 'RE1036', 'REFO2000', 'REFO2052', 'REFT4040', 'REFT4066', 'REGM3005', 'REMI1014', 'REMI1023', 'RENI1012', 'RETO1006', 'RETO1007', 'SU1001', 'SZ1002', 'SZ1004', 'TO1006', 'TO1006X', 'TO1007', 'TO1007X', 'TO1025', 'TO1032', 'TO1033', 'VO1000', 'VW5040', 'VW5040P', 'VW5053', 'LM1001');
